import 'package:flutter/material.dart';import 'package:get/get.dart';import '../controllers/auth_controller.dart';
class LoginPage extends StatefulWidget {const LoginPage({super.key});@override State<LoginPage> createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final e=TextEditingController(),p=TextEditingController();@override Widget build(BuildContext context){final c=Get.find<AuthController>();return Scaffold(appBar:AppBar(title:Obx(()=>Text('Chalo Bhai • ${c.selectedRole.value.capitalizeFirst} Login'))),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:e,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),const SizedBox(height:12),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'Password')),const SizedBox(height:20),Obx(()=>FilledButton(onPressed:c.loading.value?null:()=>c.login(e.text,p.text),child:c.loading.value?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2)):const Text('Login')))]));}}
